import React, { Component } from 'react';
import { withTheme } from 'styled-components';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Line } from 'react-chartjs-2';
import moment from 'moment';

import { ChartWrapper } from '../styles/ChessBlitzHistory.style';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

/**
 * Lichess returns one point per day the rating changed. Expand to every calendar
 * day from first to last date: each day uses the rating from the latest game on
 * or before that day (flat between games, then jump at the next data point).
 */
function expandRatingByDay(points) {
  if (!points || points.length === 0) {
    return { labels: [], values: [] };
  }

  const sorted = [...points].sort((a, b) => {
    const ta = moment({ year: a[0], month: a[1], day: a[2] }).valueOf();
    const tb = moment({ year: b[0], month: b[1], day: b[2] }).valueOf();
    return ta - tb;
  });

  const start = moment({
    year: sorted[0][0],
    month: sorted[0][1],
    day: sorted[0][2],
  }).startOf('day');
  const end = moment({
    year: sorted[sorted.length - 1][0],
    month: sorted[sorted.length - 1][1],
    day: sorted[sorted.length - 1][2],
  }).startOf('day');

  const labels = [];
  const values = [];
  let k = 0;

  for (let d = start.clone(); d.isSameOrBefore(end, 'day'); d.add(1, 'day')) {
    while (
      k + 1 < sorted.length &&
      moment({
        year: sorted[k + 1][0],
        month: sorted[k + 1][1],
        day: sorted[k + 1][2],
      })
        .startOf('day')
        .isSameOrBefore(d, 'day')
    ) {
      k += 1;
    }
    labels.push(d.format('YYYY-MM-DD'));
    values.push(sorted[k][3]);
  }

  return { labels, values };
}

class BlitzHistory extends Component {
  constructor() {
    super();
    this.state = {
      x: [],
      y: [],
    };
  }

  componentDidMount() {
    const URL = "https://lichess.org/api/user/danielwong4/rating-history";

    fetch(URL)
      .then((response) => response.json())
      .then((response) => {
        const blitzData = response.find(item => item.name === 'Blitz');
        const points = blitzData.points;

        const { labels, values } = expandRatingByDay(points);

        this.setState({ x: labels, y: values });
      });
  }

  render() {
    const { theme } = this.props;
    const fg = theme.textColor || '#000';
    const grid =
      fg === 'white' || fg === '#fff' || fg === '#ffffff'
        ? 'rgba(255,255,255,0.14)'
        : 'rgba(0,0,0,0.12)';

    const data = {
      labels: this.state.x,
      datasets: [
        {
          label: 'Blitz Rating',
          data: this.state.y,
          borderColor: fg,
          backgroundColor: fg,
          tension: 0,
          stepped: 'before',
          pointRadius: 0,
          pointHoverRadius: 4,
          borderWidth: 2,
          hitRadius: 6,
        },
      ],
    };

    const options = {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: {
          labels: { color: fg, font: { family: 'Inter' } },
        },
        title: {
          display: true,
          text: 'Lichess Blitz Rating History',
          color: fg,
          font: { family: 'Inter', size: 15 },
        },
        tooltip: {
          titleFont: { family: 'Inter' },
          bodyFont: { family: 'Inter' },
        },
      },
      scales: {
        x: {
          title: {
            display: true,
            text: 'Date',
            color: fg,
            font: { family: 'Inter' },
          },
          ticks: {
            color: fg,
            maxRotation: 45,
            minRotation: 0,
            autoSkip: true,
            maxTicksLimit: 12,
          },
          grid: { color: grid },
        },
        y: {
          title: {
            display: true,
            text: 'Rating',
            color: fg,
            font: { family: 'Inter' },
          },
          ticks: { color: fg },
          grid: { color: grid },
        },
      },
    };

    return (
      <ChartWrapper>
        <Line data={data} options={options} />
      </ChartWrapper>
    );
  }
}

export default withTheme(BlitzHistory);
